# ruff: noqa: E501 (records and parcel texts are long hex and base-32 strings)
"""Signed records and parcels for tests, made once and pasted here.

The api never signs, so its tests cannot make records. These were made the way the web
client makes them: a WebCrypto P-256 key, the body built by the core's WebAssembly build,
signed by WebCrypto, the record assembled by the core (core/bindings/wasm/fortymm-core.mjs).
HELLO_UAT is the golden vector "hello" (core/vectors/vectors.json).
"""

from dataclasses import dataclass


@dataclass(frozen=True)
class Made:
    """One `match` record, and a parcel holding only it."""

    record: str  # the standalone record, hex
    id: str  # its record id, which is also its match id, hex
    signer: str  # the key that signed it, hex
    text: str  # the parcel text
    sides: tuple[list[str], list[str]]
    terms: str


# Development (3): side one 11..11, side two 22..22, terms 01.
FIRST_MATCH = Made(
    record="",
    id="e2622c7d5d9d71fadfe41602761bdaa795e91f1f3bceb500c91fdeacef236eb3",
    signer="02ff7c922123fc9a8bfe2b5747dd3163e16eaafbc4a7a5c80912f920117b5ce3ad",
    text="",
    sides=(["11" * 32], ["22" * 32]),
    terms="01",
)

# Development (3): doubles, 33..33 and 44..44 against 55..55 and 66..66, terms 0202.
SECOND_MATCH = Made(
    record="",
    id="79aade481d045e77f74a2618df313159d6addfe112c5807581e68aca5b9ee908",
    signer="02bc94072255fbd36f52e08f3ea5fa822644ba61e5bebf44ab4baa178b93630173",
    text="",
    sides=(["33" * 32, "44" * 32], ["55" * 32, "66" * 32]),
    terms="0202",
)

# UAT (2): side one 77..77, side two 88..88, no terms.
UAT_MATCH = Made(
    record="",
    id="e33bd77a33d882fe26bae98395fcc4d323e4ec30189c011a31d62ef66cd2519d",
    signer="03bc7dc9c2af08be63cdb554e3b596b802ebdbeb0b497ca5c82bac8230cb65c49e",
    text="",
    sides=(["77" * 32], ["88" * 32]),
    terms="",
)

